    { const char * tb_v1474 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1474; }
    { const char * tb_v1475 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1475; }
