    { const char * tb_v1494 = "static void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1494; }
    { const char * tb_v1495 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1495; }
