    { const char * tb_v1522 = "    if (d->pos && !(tb_nchunks > 0 && tb_in_temp(d->pos))) free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v1522; }
    { const char * tb_v1523 = "    d->pos = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1523; }
