    { const char * tb_v1650 = "    p += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1650; }
    { const char * tb_v1651 = "    left -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1651; }
    { const char * tb_v1652 = "    memset(r, 0, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1652; }
