    { const char * tb_v1654 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1654; }
    { const char * tb_v1655 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1655; }
    { const char * tb_v1656 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1656; }
